  "claim": {
    "component_id": "C062.component",
    "value": "Experimental conclusions are restricted to the tested cohort, concurrency range, worker versions, and operating conditions.",
    "scope": "General applicability boundary on the mapping's experimental conclusions, including its conditional mechanistic and deployment interpretations.",
    "provenance": {
      "refs": [
