          "source_id": "P040",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P040 explicitly supplies these applicability bounds and requires staged confirmation for broader deployment."
    }
  },
  "signal_basis": {
    "component_id": "C062.signal_basis",
    "value": "A controlled reduction in canary concurrency produces measured temporal responses in queue depth, completion rate, and phase durations, compared with baseline and any unchanged pool. These responses are observed under particular workloads and resource conditions, with possible disturbances, comparison-pool contamination, and nonlinear dependence on the chosen step.",
    "scope": "The proposed experiment's local response, assumed observed for this judgment; the mapping reports no completed measurements.",
